ALTER TABLE plaid_items ADD COLUMN provider_item_id TEXT;
ALTER TABLE plaid_accounts ADD COLUMN provider_account_id TEXT;
ALTER TABLE mobile_connections ADD COLUMN provider_item_id TEXT;
ALTER TABLE mobile_connection_operations ADD COLUMN request_digest TEXT;
ALTER TABLE sync_state ADD COLUMN connection_revision INTEGER NOT NULL DEFAULT 1;
ALTER TABLE sync_state ADD COLUMN requested_generation INTEGER NOT NULL DEFAULT 0;
ALTER TABLE sync_state ADD COLUMN completed_generation INTEGER NOT NULL DEFAULT 0;
ALTER TABLE sync_state ADD COLUMN recurring_enqueued_generation INTEGER NOT NULL DEFAULT 0;
ALTER TABLE sync_state ADD COLUMN lifecycle TEXT NOT NULL DEFAULT 'active';
UPDATE plaid_items SET provider_item_id=item_id;
UPDATE plaid_accounts SET provider_account_id=plaid_account_id;
UPDATE mobile_connections SET provider_item_id=item_id;
INSERT OR IGNORE INTO sync_state(connection_id,provider,ledger_id)  SELECT 'plaid:' || item_id,'plaid',ledger_id FROM plaid_items;
CREATE INDEX IF NOT EXISTS plaid_items_raw_idx ON plaid_items(provider_item_id,ledger_id);
CREATE UNIQUE INDEX IF NOT EXISTS plaid_accounts_raw_idx ON plaid_accounts(ledger_id,item_id,provider_account_id);
CREATE TRIGGER IF NOT EXISTS plaid_item_initial_state AFTER INSERT ON plaid_items BEGIN  INSERT OR IGNORE INTO sync_state(connection_id,provider,ledger_id) VALUES ('plaid:' || NEW.item_id,'plaid',NEW.ledger_id);  UPDATE plaid_items SET provider_item_id=NEW.item_id WHERE item_id=NEW.item_id AND provider_item_id IS NULL AND ledger_id='personal'; END;
CREATE TRIGGER IF NOT EXISTS plaid_account_legacy_raw AFTER INSERT ON plaid_accounts  WHEN NEW.provider_account_id IS NULL AND NEW.ledger_id='personal' BEGIN  UPDATE plaid_accounts SET provider_account_id=NEW.plaid_account_id WHERE plaid_account_id=NEW.plaid_account_id; END;
CREATE TRIGGER IF NOT EXISTS mobile_connection_active_item_insert BEFORE INSERT ON mobile_connections  WHEN NEW.state IN ('connected','syncing','disconnecting') AND NOT EXISTS  (SELECT 1 FROM plaid_items p WHERE p.item_id=NEW.item_id AND p.ledger_id=NEW.ledger_id)  BEGIN SELECT RAISE(ABORT,'mobile connection item ownership mismatch'); END;
CREATE TRIGGER IF NOT EXISTS mobile_connection_active_item_update BEFORE UPDATE ON mobile_connections  WHEN NEW.state IN ('connected','syncing','disconnecting') AND NOT EXISTS  (SELECT 1 FROM plaid_items p WHERE p.item_id=NEW.item_id AND p.ledger_id=NEW.ledger_id)  BEGIN SELECT RAISE(ABORT,'mobile connection item ownership mismatch'); END;
CREATE TABLE IF NOT EXISTS plaid_account_ownership (  account_id TEXT PRIMARY KEY REFERENCES accounts(id), ledger_id TEXT NOT NULL REFERENCES ledgers(id),  item_id TEXT NOT NULL, provider_account_id TEXT NOT NULL,  UNIQUE(ledger_id,item_id,provider_account_id) );
INSERT INTO plaid_account_ownership(account_id,ledger_id,item_id,provider_account_id)  SELECT account_id,ledger_id,item_id,provider_account_id FROM plaid_accounts;
INSERT INTO plaid_account_ownership(account_id,ledger_id,item_id,provider_account_id) SELECT a.id,a.ledger_id,MIN(t.plaid_item_id),substr(a.id,7) FROM accounts a JOIN transactions t ON t.account_id=a.id AND t.ledger_id=a.ledger_id AND t.source='plaid' WHERE a.ledger_id='personal' AND a.status='import_only' AND a.id LIKE 'plaid-%' AND length(a.id)>6 AND NOT EXISTS(SELECT 1 FROM plaid_account_ownership o WHERE o.account_id=a.id) AND NOT EXISTS(SELECT 1 FROM transactions missing WHERE missing.account_id=a.id AND missing.source='plaid' AND (missing.ledger_id<>a.ledger_id OR missing.plaid_item_id IS NULL OR missing.plaid_item_id='')) AND NOT EXISTS(SELECT 1 FROM transaction_source_records r LEFT JOIN transactions linked ON linked.id=r.transaction_id WHERE r.source_kind='plaid' AND (r.account_id=a.id OR linked.account_id=a.id) AND (r.ledger_id IS NOT a.ledger_id OR r.account_id IS NOT a.id OR linked.account_id IS NOT a.id OR linked.source IS NOT 'plaid' OR r.provider_item_id IS NOT linked.plaid_item_id OR NOT ((COALESCE(length(r.provider_transaction_id),0)>0 AND r.provider_transaction_id IS linked.provider_transaction_id) OR (r.provider_transaction_id IS NULL AND COALESCE(length(r.provider_pending_transaction_id),0)>0 AND r.provider_pending_transaction_id IS linked.provider_pending_transaction_id)) OR (r.provider_pending_transaction_id IS NOT NULL AND r.provider_pending_transaction_id IS NOT linked.provider_pending_transaction_id))) GROUP BY a.id,a.ledger_id HAVING COUNT(DISTINCT t.plaid_item_id)=1;
CREATE TRIGGER IF NOT EXISTS plaid_ownership_insert BEFORE INSERT ON plaid_account_ownership BEGIN  SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM accounts WHERE id=NEW.account_id AND ledger_id=NEW.ledger_id)  OR EXISTS(SELECT 1 FROM plaid_account_ownership WHERE account_id=NEW.account_id AND    (ledger_id<>NEW.ledger_id OR item_id<>NEW.item_id OR provider_account_id<>NEW.provider_account_id))  OR EXISTS(SELECT 1 FROM plaid_account_ownership WHERE ledger_id=NEW.ledger_id AND item_id=NEW.item_id    AND provider_account_id=NEW.provider_account_id AND account_id<>NEW.account_id)  THEN RAISE(ABORT,'immutable Plaid account ownership') END; END;
CREATE TRIGGER IF NOT EXISTS plaid_ownership_update BEFORE UPDATE ON plaid_account_ownership  WHEN NEW.account_id<>OLD.account_id OR NEW.ledger_id<>OLD.ledger_id OR NEW.item_id<>OLD.item_id OR NEW.provider_account_id<>OLD.provider_account_id  BEGIN SELECT RAISE(ABORT,'immutable Plaid account ownership'); END;
